package fixture
import("bytes";"encoding/hex";"fmt";mp4 "github.com/Eyevinn/mp4ff/mp4")
// Source builds a four-sample source, using the production box encoders.
func Source(gap bool)([]byte,error){init:=mp4.CreateEmptyInit();init.Moov.Mvhd.Timescale=1000;t:=init.AddEmptyTrack(1000,"video","und");sps,_:=hex.DecodeString("674d401fe4605017fcb80b4f00000300010000030032e4800753003a9e08200e58e189c0");pps,_:=hex.DecodeString("685bdf20");if e:=t.SetAVCDescriptor("avc1",[][]byte{sps},[][]byte{pps},true);e!=nil{return nil,e};var b bytes.Buffer;if e:=init.Encode(&b);e!=nil{return nil,e};for j:=0;j<2;j++{f,e:=mp4.CreateFragment(uint32(j+1),1);if e!=nil{return nil,e};base:=uint64(j*20);if gap&&j==1{base=40};for k:=0;k<2;k++{f.AddFullSample(mp4.FullSample{Sample:mp4.Sample{Flags:mp4.SampleFlags{SampleDependsOn:2}.Encode(),Dur:10,Size:2},DecodeTime:base+uint64(k*10),Data:[]byte{byte('A'+j*2+k),byte(j*2+k)}})};if e=f.Encode(&b);e!=nil{return nil,e}};return b.Bytes(),nil}
func Inspect(b []byte)([]uint32,[]byte,uint64,error){f,e:=mp4.DecodeFile(bytes.NewReader(b));if e!=nil{return nil,nil,0,e};if f.IsFragmented()||f.Moov==nil||len(f.Moov.Traks)!=1{return nil,nil,0,fmt.Errorf("not single-track progressive output")};t:=f.Moov.Traks[0];s,e:=t.GetSampleData(1,t.GetNrSamples());if e!=nil{return nil,nil,0,e};d:=make([]uint32,len(s));for i,v:=range s{d[i]=v.Dur};p,e:=f.ReadSampleData(t,1,t.GetNrSamples(),bytes.NewReader(b),nil);return d,p,t.Mdia.Mdhd.Duration,e}
func VerifyNormal(b []byte)error{d,p,dur,e:=Inspect(b);if e!=nil{return e};if len(d)!=4||dur!=40||!bytes.Equal(p,[]byte{'A',0,'B',1,'C',2,'D',3}){return fmt.Errorf("wrong sample identity/count/duration: %v %d",d,dur)};for _,v:=range d{if v!=10{return fmt.Errorf("changed normal packet duration: %v",d)}};return nil}
